package shortestpath.overlay;

import java.awt.Color;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import shortestpath.WorldPointUtil;
import shortestpath.transport.Transport;

/**
 * Debug aid for checking new transport data in game: the rows listed in
 * /debug/new_transports.tsv (generated by scripts/list_new_transports.py) are
 * drawn in their own colour by the transport debug overlays.
 */
@Slf4j
final class NewTransportHighlights
{
	static final Color COLOR = Color.CYAN;
	private static final String RESOURCE = "/debug/new_transports.tsv";

	@Value
	static class Entry
	{
		int origin;
		int destination;
		String label;
	}

	private static final List<Entry> ENTRIES = load();
	private static final Set<Long> EDGES = edges(ENTRIES);

	private NewTransportHighlights()
	{
	}

	static List<Entry> entries()
	{
		return ENTRIES;
	}

	static boolean isNew(int origin, Transport transport)
	{
		return EDGES.contains(key(origin, transport.getDestination()));
	}

	private static long key(int origin, int destination)
	{
		return ((long) origin << 32) | (destination & 0xffffffffL);
	}

	private static Set<Long> edges(List<Entry> entries)
	{
		Set<Long> edges = new HashSet<>();
		for (Entry entry : entries)
		{
			edges.add(key(entry.getOrigin(), entry.getDestination()));
		}
		return edges;
	}

	private static List<Entry> load()
	{
		List<Entry> entries = new ArrayList<>();
		try (InputStream in = NewTransportHighlights.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				return Collections.emptyList();
			}
			BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.startsWith("#") || line.isBlank())
				{
					continue;
				}
				String[] cells = line.split("\t", -1);
				int destination = parse(cells[1]);
				if (destination == WorldPointUtil.UNDEFINED)
				{
					continue;
				}
				entries.add(new Entry(parse(cells[0]), destination, cells.length > 2 ? cells[2] : ""));
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read {}", RESOURCE, e);
		}
		return Collections.unmodifiableList(entries);
	}

	private static int parse(String cell)
	{
		String[] parts = cell.trim().split(" ");
		if (parts.length != 3)
		{
			return Transport.UNDEFINED_ORIGIN;
		}
		return WorldPointUtil.packWorldPoint(
			Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
	}
}
